F=[dict(id='F-value',meaning='Stored command attributes and status associated with the local instance, with bal used for promise checks and vbal reported as value provenance; status does not necessarily advance on an Accept handler update.',identity={'replica':'InstanceSpace row','instance':'InstanceSpace index'},validity_context='One local replica and current instance state; revised by protocol and recovery handlers.',representation=['Instance.Cmds','Instance.Seq','Instance.Deps','Instance.Status','Instance.bal','Instance.vbal'],durability='In memory in the configured Durable=false server path; optional persistence is not assumed to reconstruct it.',recovery='Prepare reports stored fields; recovery selection may reuse or replace them.',source_ids=['S-phase1','S-formation','S-commit','S-recovery'],invalidators=[],reinterpreters=['B-select','B-authority'],unknowns=[]),dict(id='F-prepare',meaning='The producer-side PrepareReply reports the local promise, value ballot, status and attributes for a requested instance. This assertion is about the constructed reply, not guaranteed end-to-end transport preservation.',identity={'acceptor':'AcceptorId','replica':'Replica','instance':'Instance','request_context':'Ballot reported after handling Prepare'},validity_context='Reply construction in handlePrepare, or self report construction in startRecoveryForInstance; fields describe that producer point.',representation=['PrepareReply.Ballot','PrepareReply.VBallot','PrepareReply.Status','PrepareReply.Command','PrepareReply.Seq','PrepareReply.Deps'],durability='Transient message and recovery bookkeeping.',recovery='handlePrepareReply consumes VBallot to select retained support after matching request Ballot.',source_ids=['S-recovery','S-messages','S-wire'],invalidators=[],reinterpreters=['B-select'],unknowns=['Whether serialization preserves the value provenance needed by the consumer.']),dict(id='F-decision',meaning='A local instance is marked COMMITTED or later EXECUTED with command attributes, permitting dependency-ordered consumption; this records the implementation state rather than proving cluster agreement.',identity={'replica':'Instance row','instance':'Instance index'},validity_context='Current local instance after formation, commit delivery or recovery selection.',representation=['Instance.Status','Instance.Cmds','Instance.Seq','Instance.Deps'],durability='Volatile in default deployment.',recovery='Committed reports may be selected during recovery; full Commit distributes commands.',source_ids=['S-formation','S-commit','S-recovery','S-exec'],invalidators=[],reinterpreters=[],unknowns=[])]
activity_text=[('A1','Qualified support for formation and advancement','Local owner batches commands, forms dependency attributes, counts qualified phase replies, and propagates full decisions; Accept update/status discrepancy remains open.',['S-phase1','S-formation','S-commit']),('A2','Context validity and authority transitions','Per-instance bal promises reject older requests; lastTriedBallot qualifies replies. Recovery gathers prior support and chooses a path via VBallot/status. Master IsLeader is retry preference, not exclusive proposal authority.',['S-ballot','S-recovery']),('A3','Recover eligible participation','Executor detects incomplete known prefixes and queues per-instance recovery; recovery selection and transport are implementation-owned.',['S-dispatch','S-recovery']),('A4','Participant eligibility','Fixed peer addresses and Alive/preferred order control recipients; quorum sizes derive from N/F. No dynamic membership path established.',['S-members','S-run','S-master']),('A5','Decision application','Committed dependency graph is traversed as SCCs; commands are applied and marked EXECUTED.',['S-exec']),('A6','History and support reconstruction','Stored bal/vbal/status/attributes are exposed through PrepareReply transport. Optional disk methods exist but default deployment disables Durable and no reconstruction was established.',['S-recovery','S-wire','S-store','S-run']),('A7','Client invocation and completion','PROPOSE enters a delayed channel; owner retains client metadata; default replies follow execution. Retry duties remain unread.',['S-client','S-phase1','S-exec'])]
