M=dict(version=1,target_profile=dict(system_boundary='Captured Go EPaxos package plus its in-repository replica, RPC, master, state and server-entry support; other protocol implementations are outside this initial map.',protocol_contexts=['Per-instance row/index and ballot','Static participant set; default volatile server deployment'],external_interfaces=['PROPOSE client messages','Registered peer RPC messages','Master BeTheLeader RPC'],ownership=['Protocol run goroutine owns handlers; executor is separate','Master owns registration and leader preference; per-instance owners form commands'],selection_injection=['Thrifty=true in EPaxos constructor; Durable=false, transconf=false in server entry'],source_ids=['S-init','S-run','S-members'],unknowns=['Restart reconstruction and client retry duties not established']),activities=A,behaviors=B,facts=F,surfaces=S)
M['core_overview']=dict(status='usable',rationale='Representative formation, transfer of per-instance authority, prior support, transport and application paths have been traced. Usability describes navigation, not correctness or exhaustive coverage.',formation=dict(explanation='A proposal is batched into its receiving replica row and starts phase 1 with owner-ID ballot. Conflict indices establish Seq/Deps. Thrifty PreAccept reaches selected alive peers, whose reports are qualified by lastTriedBallot and phase status. The owner merges attributes and either fast commits under threshold/equality/initial-ballot conditions (with a small-cluster exception) or broadcasts Accept and commits after a majority count. Full Commit carries commands and attributes; receivers reject stale ballots and already established decisions. Default Dreply=true delays client response until dependency/SCC execution. Sender and receiver codecs, not just handler structs, are part of this relationship.',behavior_ids=['B-propose','B-preaccept','B-form','B-accept','B-learn','B-exec','B-config'],fact_ids=['F-value','F-decision'],source_ids=['S-phase1','S-formation','S-bcast','S-commit','S-exec','S-members']),context=dict(explanation='Authority is per row/instance. inst.bal guards incoming work; leader bookkeeping lastTriedBallot guards phase replies. Executor-driven recovery replaces local attempt bookkeeping while retaining proposals and stored value; generated ballots depend on ID/N and optionally maxRecvBallot under master-granted IsLeader. Prepare raises the promise and reports prior vbal/status/attributes. A slow quorum including the self report selects support using VBallot, then preserves a reported committed state, accepts retained support, or restarts phase 1. Prior committed instances with commands bypass recovery. No global revocation mechanism was found; stale work is handled by these local promise/status/phase checks, whose actual strength remains investigable.',behavior_ids=['B-authority','B-prepare','B-select','B-recover-trigger','B-wire'],fact_ids=['F-value','F-prepare'],source_ids=['S-ballot','S-recovery','S-dispatch','S-wire','S-master']),connection=dict(explanation='Recovery authority does not independently determine a new value: its consumer uses reported support provenance/status and attributes to decide which formation path is eligible. bal may rise while vbal and prior attributes remain in handlePrepare, separating promise from support. The local recovery entry instead updates both ballots before self reporting; remote replies cross a codec that omits VBallot. These discrepancies are unresolved premises of support preservation, not assumed agreement failures. Old phase replies face attempt/phase guards; established commit messages have status/ballot guards. Pending client proposals are retained across recovery and sometimes requeued after NOOP; consumption still requires complete committed dependencies.',behavior_ids=['B-prepare','B-wire','B-select','B-form','B-authority','B-learn','B-exec'],fact_ids=['F-value','F-prepare','F-decision'],source_ids=['S-recovery','S-wire','S-formation','S-commit','S-exec']),core_gaps=[],open_details=['PrepareReply transport provenance preservation is the first discriminator.','Accept status, recovery self provenance, ballot reuse and tie selection require separate legal-history investigation.','Optional durability/restart scope, client retries, SCAN ranges and execution-order ties remain open.'])
q=dict(question='Does the PrepareReply transport preserve the handler-produced VBallot required by recovery support selection, or does decoding a fresh message erase nonzero value provenance?',importance='Incorrect provenance can cause recovery to rank prior support incorrectly during authority transfer; the local transport responsibility can be checked without asserting a whole-cluster agreement failure.',source_ids=['S-recovery','S-wire','S-send','S-receive','S-messages','S-rpc'],participants=['Acceptor','Recovering instance owner'],objects=['PrepareReply','Instance'],contexts=['Volatile static-membership EPaxos','Prepare handling after a nonzero owner ballot'],event_paths=['handlePreAccept -> handlePrepare -> replyPrepare -> SendMsg/Marshal -> New/Unmarshal -> handlePrepareReply'],activity_classes=['A6','A2','A1'],behavior_ids=['B-prepare','B-authority','B-wire','B-select'],fact_ids=['F-prepare'],supporting_behavior_ids={'B-preaccept':'Establishes the prior instance vbal under a nonzero original owner ballot.'},obligation_relation_kind='preservation',counterevidence=['Ballot, identity, status and payload fields are serialized; Ballot equality still qualifies recovery reports.','The self PrepareReply is appended without transport; omission affects remote reports, not every report.','VBallot zero is preserved incidentally when that is the produced value.'],unknowns=['Need a fixed execution observing a reply produced by actual handlers, byte encoding/decoding and resulting VBallot for the same identity.','Broader selected-value or agreement consequences require additional legal-history work; not entailed by a local codec discrepancy.'],trigger_rationale='The producer explicitly reports inst.vbal, and the consumer uses VBallot for highest-support selection, while the complete PrepareReply codec has no VBallot read or write. A small handler-to-codec check is more discriminating and cheaper than a cluster schedule; persistence applicability is weaker because normal server entry disables it.',disposition='concrete_suspicion',preferred_check='direct_test')
